// Expected paths and body bytes are authored inputs, never regenerated by conversion.
export const exportArtifacts = () => [
  {
    fileId: "opaque",
    relativePath: "著者/題😀_converted2.md",
    format: "md",
    bytes: new Uint8Array([239, 187, 191, 0, 13, 10, 255]),
  },
  {
    fileId: "empty",
    relativePath: "空.txt",
    format: "txt",
    bytes: new Uint8Array(),
  },
  {
    fileId: "decomposed",
    relativePath: "e\u0301.md",
    format: "md",
    bytes: new TextEncoder().encode("青［＃未対応］\r\n"),
  },
  {
    fileId: "other",
    relativePath: "別著者/題😀_converted2.md",
    format: "md",
    bytes: new Uint8Array([239, 187, 191, 0, 13, 10, 255]),
  },
];
export const equal = (actual, expected, label) => {
  if (JSON.stringify(actual) !== JSON.stringify(expected))
    throw Error(
      label + ": " + JSON.stringify(actual) + " != " + JSON.stringify(expected),
    );
};
export async function runExportContract(prepare) {
  let passed = 0;
  const cases = [];
  const check = (name, actual, expected) => {
    equal(actual, expected, name);
    passed++;
    cases.push(name);
  };
  const artifacts = exportArtifacts();
  const zip = await prepare(artifacts, { mode: "zip" });
  check("zip ready", zip.status, "ready");
  check("default archive name", zip.filename, "aozora-markdown.zip");
  check(
    "ordered manifest",
    zip.manifest,
    artifacts.map(({ fileId, relativePath, format, bytes }) => ({
      fileId,
      relativePath,
      format,
      byteLength: bytes.length,
    })),
  );
  check(
    "same bytes repeat",
    [...(await prepare(artifacts, { mode: "zip" })).bytes],
    [...zip.bytes],
  );
  for (const format of ["md", "txt"]) {
    const input = {
      ...artifacts[0],
      relativePath: "著者/題." + format,
      format,
    };
    const r = await prepare([input], { mode: "single" });
    check(format + " single ready", r.status, "ready");
    check(format + " exact bytes", [...r.bytes], [...input.bytes]);
    check(format + " basename", r.filename, "題." + format);
  }
  check(
    "empty file ready",
    (await prepare([artifacts[1]], { mode: "single" })).status,
    "ready",
  );
  for (const [name, inputs, options, code] of [
    ["no selection", [], { mode: "zip" }, "NO_ARTIFACTS"],
    ["multi single", artifacts, { mode: "single" }, "SINGLE_FILE_COUNT"],
    [
      "id duplicate",
      [artifacts[0], { ...artifacts[1], fileId: "opaque" }],
      { mode: "zip" },
      "DUPLICATE_FILE_ID",
    ],
    [
      "bad path",
      [{ ...artifacts[0], relativePath: "../bad.md" }],
      { mode: "zip" },
      "UNSAFE_PATH",
    ],
    [
      "case collision",
      [
        { ...artifacts[0], relativePath: "a.md" },
        { ...artifacts[2], relativePath: "A.md" },
      ],
      { mode: "zip" },
      "PATH_COLLISION",
    ],
    [
      "prefix collision",
      [
        { ...artifacts[0], relativePath: "a.md" },
        { ...artifacts[2], relativePath: "a.md/b.md" },
      ],
      { mode: "zip" },
      "PATH_COLLISION",
    ],
    [
      "bad archive",
      artifacts,
      { mode: "zip", archiveName: "../a.zip" },
      "INVALID_ARCHIVE_NAME",
    ],
    [
      "output budget",
      artifacts,
      { mode: "zip", limits: { maxOutputBytes: 1 } },
      "OUTPUT_BYTES_LIMIT",
    ],
    [
      "input budget",
      artifacts,
      { mode: "zip", limits: { maxInputBytes: 1 } },
      "INPUT_BYTES_LIMIT",
    ],
    [
      "bad limit",
      artifacts,
      { mode: "zip", limits: { maxFiles: 0 } },
      "INVALID_LIMIT",
    ],
  ]) {
    const r = await prepare(inputs, options);
    check(
      name,
      [r.status, r.diagnostics[0].code, "bytes" in r, r.metrics.readyFiles],
      ["failed", code, false, 0],
    );
  }
  const view = new Uint8Array([99, 0, 1, 255, 99]).subarray(1, 4);
  const single = await prepare([{ ...artifacts[0], bytes: view }], {
    mode: "single",
  });
  check("view offset", [...single.bytes], [0, 1, 255]);
  single.bytes.fill(42);
  check("independent buffer", [...view], [0, 1, 255]);
  check(
    "caller unchanged",
    [...artifacts[0].bytes],
    [239, 187, 191, 0, 13, 10, 255],
  );
  return { passed, cases, zip: [...zip.bytes], metrics: zip.metrics };
}
